def main():
    torch.set_num_threads(3);out=ROOT/'models/truth_v31';cache=ROOT/'cache/truth_v31';assert json.loads((out/'joint_validation.json').read_text())['passed']
    with (out/'evaluation_once.json').open('x') as f:json.dump(dict(candidate_sha256=hashlib.sha256((out/'joint_candidate.pt').read_bytes()).hexdigest()),f)
    rows=json.loads((cache/'rows.json').read_text(encoding='utf-8'));d=torch.load(cache/'features.pt',weights_only=True);x=d['x'];n=len(rows);brands=d['brands'];ck=torch.load(out/'joint_candidate.pt',weights_only=True);mc=ck['model_head'];pairs=list(map(tuple,mc['pairs']));keys=[b+'|'+m for b,m in pairs];mapping=torch.tensor([brands.index(b) for b,m in pairs]);mh=CosineMakeHead(torch.zeros(len(brands),1280)).eval();mh.load_state_dict(ck['head']);fh=CosineMakeHead(torch.zeros(len(pairs),1280)).eval();fh.load_state_dict(mc['head']);ti=torch.tensor([i for i,r in enumerate(rows) if r['split']=='test']);tr=[rows[int(i)] for i in ti];indices=torch.cat([ti,ti+n]);known=lambda r:(r['brand'],r.get('family')) in pairs and not r['image'].startswith('make_scope_v23/');fi=torch.tensor([i for i in ti if known(rows[int(i)])]);fr=[rows[int(i)] for i in fi];fidx=torch.cat([fi,fi+n]);edge=torch.load(ROOT/'cache/truth_v30/edge_test.pt',weights_only=True);assert edge['indices']==fi.tolist();q=torch.cat([x[indices],edge['x']]);geom=torch.cat([valid(tr),valid(tr,'phone'),torch.ones(len(fr),dtype=torch.bool)]);familygeom=torch.cat([valid(tr,'whole',True),valid(tr,'phone',True),edge['geometry']])
    with torch.inference_mode():
        p=(mh(q)/ck['temperature']).softmax(1);op,oa=route(p,references(q,ck['retrieval'],len(brands)),ck['thresholds'],ck['retrieval']['fallback_thresholds'],brands,geom);fp=(fh(q)/mc['temperature']).softmax(1);v,ii=fp.topk(2,dim=1);g=torch.tensor([mc['thresholds'][keys[int(j)]] for j in ii[:,0]]);sim=q@torch.nn.functional.normalize(fh.weight,dim=1).T;sg=torch.tensor([mc['similarity_thresholds'][keys[int(j)]] for j in ii[:,0]]);direct=familygeom&(g<1)&(v[:,0]>=g)&((v[:,0]-v[:,1])>=mc['margin'])&(sim.gather(1,ii[:,:1])[:,0]>=sg);mp=torch.zeros(len(q),len(brands));mp.scatter_add_(1,mapping.expand(len(q),-1),fp);fallback=(~oa)&direct;cp=torch.where(fallback[:,None],mp,op);ca=oa|fallback
